function esc(s) {
  return String(s === undefined || s === null ? '' : s);
}

const first = $input.first();
const e = (first && first.json) || {};
const workflowName = esc((e.workflow && e.workflow.name) || 'unknown workflow');

let msg, marker, url;

if (e.execution && e.execution.error) {
  const err = e.execution.error || {};
  const rawMsg = String(err.message || 'unknown error');
  const desc = String(err.description || '');
  msg = rawMsg;
  if (desc && desc !== rawMsg) msg += ' — ' + desc.split('\n')[0].slice(0, 300);
  marker = '📍 ' + esc(e.execution.lastNodeExecuted || 'unknown node');
  url = e.execution.url || '';
} else if (e.trigger && e.trigger.error) {
  const err = e.trigger.error || {};
  const rawMsg = String(err.message || 'unknown error');
  const desc = String(err.description || '');
  msg = rawMsg;
  if (desc && desc !== rawMsg) msg += ' — ' + desc.split('\n')[0].slice(0, 300);
  marker = '⚡ trigger error' + (e.trigger.mode ? ' (' + esc(e.trigger.mode) + ')' : '');
  url = '';
} else {
  msg = 'unknown error';
  marker = '';
  url = '';
}

const lines = ['🔴 **' + workflowName + '**'];
if (marker) lines.push(marker);
lines.push(esc(msg.slice(0, 500)));
if (url) lines.push('🔗 ' + url);

return [{ json: { content: lines.join('\n') } }];
